// DayZ-Expansion-Market tuning: reshapes trader stock across every category
// the custom trader city sells into a hand-classified rarity system
// (Common/Uncommon/Rare/Legendary) instead of DayZ-Expansion-Market's own
// flat per-category defaults (every category ships InitStockPercent: 75.0
// and MaxStockThreshold: 100 regardless of what it sells).
//
// Source categories (Assault_Rifles.json, Helmets.json, etc. - generated by
// DayZ-Expansion-Market and never modified here) are merged/reorganized
// into a curated set (see MERGED_CATEGORIES) with per-item rarity tiers
// driving MaxStockThreshold, BUY_PRICE_MULTIPLIER, and
// SELL_PRICE_PERCENT_OVERRIDE. The companion EnforceScript addon
// (DZSurvivalTraderRestock) infers an item's tier at runtime purely from
// its live MaxStockThreshold (see that addon's TierForCap()) - keep
// TIER_MAX_STOCK below and that addon's thresholds in sync.
//
// Merging reads each source category's still-pristine JSON and writes a
// brand new category file, copying every item's price fields verbatim -
// only MaxStockThreshold (and price, via BUY_PRICE_MULTIPLIER/
// priceOverrides) is ever changed. Source files are never touched directly
// (just quarantined, see quarantineConsumedSourceCategories()), so
// re-running this on every server start regenerates the same output.
//
// IMPORTANT: DayZ-Expansion-Market's LoadCategories() scans its whole
// folder and loads every "*.json" file into one shared global
// classname->item map, independent of whether any trader identity
// references that category - whichever category loads a given classname
// *second* has it silently rejected, not merged. Leaving an old source
// file (e.g. Assault_Rifles.json) in place after merging it into
// MERGED_CATEGORIES would quietly steal its own items back out of the real
// merged category on every boot. quarantineConsumedSourceCategories()
// (called at the end of tuneExpansionMarket()) renames every fully-absorbed
// source file away from ".json" so the folder scan skips it, while
// readCategory() below still reads that same renamed file as this merge's
// data source.
//
// This only ever edits the category *template* files
// (profiles/ExpansionMod/Market/<Category>.json) - used to seed a brand new
// trader zone's starting stock. It never touches the live, per-zone
// running stock (expansion/traderzones/<Zone>.json's own Stock map, written
// by the game itself - see src/traders.ts's ensureCustomZone()), which is
// keyed purely by classname independent of category file, so re-running
// this never resets or lowers anything a player has actually sold in.
//
// Two categories are deliberately left OUT of the merge/tier system:
//   - Ghillies: sale-only (0% init stock, low cap, never auto-restocked) -
//     the only way this ever has stock is a player selling one in.
//   - Vehicle_Parts/Batteries: buying a vehicle also spawns its default
//     attachments (wheels, doors, battery, etc.), drawn from these
//     categories' own per-classname stock, so they need to stay generously
//     stocked - a functional necessity, not a "coveted power" category.

import { EXPANSION_MARKET_DIR } from "./paths.ts";
import { log, ok } from "./ui.ts";
import { exists } from "./steam.ts";
import { DEAD_MARKET_FILES } from "./marketGapFill.ts";

type Tier = "Common" | "Uncommon" | "Rare" | "Legendary";

// Absolute stock cap per tier - also what the companion restock addon
// reverse-engineers an item's tier from at runtime (see this file's header
// comment). Keep these thresholds and that addon's TierForCap() in sync.
export const TIER_MAX_STOCK: Record<Tier, number> = {
  Common: 20,
  Uncommon: 8,
  Rare: 3,
  Legendary: 1,
};

// Buy-price multiplier applied on top of whatever price (DayZ-Expansion-
// Market's own shipped default, or this file's own priceOverride) an item
// would otherwise land on. Buying is unaffected by MarketSettings.json's
// SellPricePercent (the buy path always uses modifier=1.0 -
// ExpansionMarketItem.CalculatePrice()), so this is the only lever for
// making purchases expensive; selling is controlled separately via
// SellPricePercent (see traders.ts's ensureHardcoreSellPricePercent()).
// Common stays at 1.0x since that tier covers the baseline survival loop
// (ammo/food/meds/basic clothes), which is deliberately not penalized.
export const BUY_PRICE_MULTIPLIER: Record<Tier, number> = {
  Common: 1.0,
  Uncommon: 1.5,
  Rare: 2.5,
  Legendary: 3.5,
};

// Per-item sell-price-percent override, layered on top of the global
// SellPricePercent (MarketSettings.json, see traders.ts's
// HARDCORE_SELL_PRICE_PERCENT). Each item's own SellPricePercent takes
// priority over the trader zone's, which takes priority over the global
// setting - all three use -1 as an "inherit the next level up" sentinel
// (ExpansionMarketTrader.GetSellPricePercent()). This project's custom
// zone leaves its own SellPricePercent at -1 (see ensureCustomZone() in
// traders.ts), so a real value here is the only way to make one item sell
// for a different percentage than another. Common/Uncommon inherit the
// 20% global default via -1; Rare/Legendary get an explicit bump so a
// lucky find is worth cashing in.
export const SELL_PRICE_PERCENT_OVERRIDE: Record<Tier, number> = {
  Common: -1,
  Uncommon: -1,
  Rare: 40,
  Legendary: 60,
};

interface SourceGroup {
  source: string;
  tier: Tier;
  only?: string[];
  exclude?: string[];
  overrides?: Record<string, Tier>;
  // Per-classname price correction for items whose DayZ-Expansion-Market
  // default price doesn't match the rarity tier they landed in here (e.g.
  // a reskin that kept a stray generic default instead of matching its
  // base item's real price).
  priceOverrides?: Record<string, { min: number; max: number }>;
  /**
   * Flat SellPricePercent applied to every item in THIS group only, taking
   * priority over both MergedCategory.sellPricePercent and the per-tier
   * SELL_PRICE_PERCENT_OVERRIDE lookup. Use when only one source group in
   * an otherwise mixed category needs its own rate.
   */
  sellPricePercent?: number;
}

interface MergedCategory {
  fileName: string;
  displayName: string;
  icon: string;
  initStockPercent: number;
  groups: SourceGroup[];
  /**
   * Flat SellPricePercent applied to every item in this merged category,
   * overriding the per-tier SELL_PRICE_PERCENT_OVERRIDE lookup entirely.
   * Use for a whole-category rule that isn't tier-dependent.
   */
  sellPricePercent?: number;
}

